<template><g class="talent-graph">
         <circle cx="1800" cy="1800" r="1760" fill="#14232f" stroke="#859aaa" stroke-opacity=".23" stroke-width="3"/>
         <path v-for="(b,key) in catalog.branches" :key="key" :d="sector(b.angle)" :fill="b.color" fill-opacity=".07" :stroke="b.color" stroke-opacity=".16" stroke-width="2"/>
         <circle cx="1800" cy="1800" r="490" fill="url(#talent-core)" stroke="#b1c2cd" stroke-opacity=".1" stroke-width="2"/>
         <circle v-for="r in [550,950,1350,1720]" :key="r" cx="1800" cy="1800" :r="r" fill="none" stroke="#b1c2cd" stroke-opacity=".055" stroke-width="2"/>
         <g v-for="edge in edges" :key="edge.key"><path :d="edge.path" fill="none" :stroke="edge.active?catalog.branches[edge.branch].color:'#41535f'" :stroke-width="edge.active?5:2" :opacity="edge.active?.85:.45"/><path v-if="edge.active" :d="edge.path" fill="none" :stroke="catalog.branches[edge.branch].color" stroke-width="13" opacity=".075"/></g>
         <g class="talent-core-label" fill="#dce5eb" text-anchor="middle"><circle cx="1800" cy="1800" r="110" fill="#223746" stroke="#9baebc" stroke-width="3"/><text x="1800" y="1821" font-size="65">✧</text><text x="1800" y="1990" font-size="38">{{state.used}} / 41</text><text x="1800" y="2040" font-size="26" opacity=".6">POINTS INVESTIS</text></g>
         <g v-for="label in labels" :key="label.key" :transform="`translate(${label.x} ${label.y})`"><text text-anchor="middle" :fill="label.color" font-size="24" font-weight="600">{{label.text}}</text></g>
         <g v-for="n in catalog.nodes" :key="n.id" :data-talent-node="n.id" class="talent-node" :class="{owned:state.nodes[n.id],chosen:selectedId===n.id,fresh:flashId===n.id}" :transform="`translate(${n.x} ${n.y})`" :style="{'--branch':catalog.branches[n.branch].color}" @click.stop="$emit('select',n)"><title>{{n.name}} · {{n.points}} point(s) · {{state.nodes[n.id]?'Acquis':available(n)||'Disponible'}}</title><circle :r="radius(n)+7" fill="transparent"/><circle v-if="selectedId===n.id" :r="radius(n)+9" fill="none" :stroke="catalog.branches[n.branch].color" stroke-width="3"/><circle :r="radius(n)" :fill="state.nodes[n.id]?catalog.branches[n.branch].color:'#23323e'" :stroke="state.nodes[n.id]||!available(n)?catalog.branches[n.branch].color:'#60717e'" :stroke-width="n.ultimate?5:3" :opacity="state.nodes[n.id]||!available(n)?1:.5"/><text text-anchor="middle" dominant-baseline="central" :font-size="n.ultimate?36:n.size==='small'?15:21" :fill="state.nodes[n.id]?'#14232f':available(n)?'#8d9aa3':catalog.branches[n.branch].color">{{state.nodes[n.id]?'✓':glyph(n)}}</text></g>
</g></template>
<script>
import catalog from '@/data/talentTree.json';
const byId=new Map(catalog.nodes.map(n=>[n.id,n]));
export default{name:'TalentTreeGraph',props:{state:Object,selectedId:String,flashId:String},data:()=>({catalog}),computed:{
  edges(){return catalog.nodes.filter(n=>!n.ultimate).flatMap(n=>(n.parents.length?n.parents:[null]).map(parent=>{const p=parent?byId.get(parent):{x:1800,y:1800};return{key:n.id+parent,branch:n.branch,active:!!this.state.nodes[n.id],path:`M${p.x},${p.y} L${n.x},${n.y}`};}));},
  labels(){return Object.entries(catalog.branches).flatMap(([key,b])=>{if(['capture','combat'].includes(key))return Object.entries(catalog.types).map(([type,text],i)=>{const angle=(key==='capture'?137.5:47.5)+i*5;return{key:key+type,text,color:b.color,x:1800+Math.cos(angle*Math.PI/180)*450,y:1800+Math.sin(angle*Math.PI/180)*450};});const a=b.angle*Math.PI/180;return[{key,text:b.name,color:b.color,x:1800+Math.cos(a)*360,y:1800+Math.sin(a)*360}];});},
},methods:{
radius(n){return {small:14,medium:20,large:27,giant:33,ultimate:48}[n.size];},glyph(n){return n.ultimate?'✧':n.branch==='combat'?'ϟ':n.branch==='capture'?'⌕':n.branch==='experience'?'↗':'₽';},
available(n){if(this.state.nodes[n.id])return null;if(this.state.available<n.points)return 'Pas assez de points disponibles.';if(this.state.branches[n.branch]+n.points>31)return '31 points maximum dans une spécialisation.';if(n.ultimate&&this.state.branches[n.branch]!==30)return 'Investis d’abord 30 points dans cette spécialisation.';if(n.parents.some(id=>!this.state.nodes[id]))return 'Débloque les talents précédents sur ce chemin.';if(n.branch==='capture'&&n.size==='giant'&&catalog.nodes.some(other=>other.branch==='capture'&&other.size==='giant'&&this.state.nodes[other.id]))return 'Un seul talent géant de recherche à la fois.';return null;},
sector(a){const p=angle=>`${1800+Math.cos(angle*Math.PI/180)*1720},${1800+Math.sin(angle*Math.PI/180)*1720}`;return `M1800,1800 L${p(a-45)} A1720,1720 0 0 1 ${p(a+45)} Z`;},}};
</script>
<style scoped>.talent-node{cursor:pointer}.talent-node text{pointer-events:none}.talent-node.fresh circle{animation:talent-purchase .8s ease-out}@keyframes talent-purchase{0%{stroke-width:16}100%{stroke-width:3}}@media(prefers-reduced-motion:reduce){.talent-node.fresh circle{animation:none}}</style>
